def earliest_arrival(n: int, connections: list[tuple[int, int, int, int]], source: int, target: int, start: int, change: int, max_transfers: int) -> int:
    if source == target:
        return start

    max_rides = max_transfers + 1
    if max_rides <= 0:
        return -1

    INF = 10**30
    prev = [INF] * n
    prev[source] = start
    best = INF

    for ride in range(1, max_rides + 1):
        cur = [INF] * n
        wait = 0 if ride == 1 else change
        reachable = False

        for u, v, depart, arrive in connections:
            at_u = prev[u]
            if at_u != INF and at_u + wait <= depart:
                if arrive < cur[v]:
                    cur[v] = arrive
                    reachable = True

        if cur[target] < best:
            best = cur[target]

        if not reachable:
            break

        prev = cur

    return -1 if best == INF else best
